<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import { api } from '../api'
import { state, label, perform, refresh, time, short } from '../state'
import type { RecordData } from '../types'
const emit = defineEmits<{ openCandidate: [id: string] }>()
const tab = ref('music'), query = ref(''), musicFile = ref<File | null>(null), chartFile = ref<File | null>(null)
const musicInput = ref<HTMLInputElement>(), chartInput = ref<HTMLInputElement>()
const musicLicense = ref('unknown'), musicActions = ref<string[]>(['local_research'])
const chart = reactive({ music_asset_id: '', chart_mode: 'regular', key_count: 4, difficulty_class: 'IN', difficulty_value: 15, license_status: 'unknown', allowed_actions: ['local_research'] as string[] })
const edit = ref<RecordData | null>(null), editKind = ref(''), editor = reactive({ license_status: 'unknown', allowed_actions: [] as string[], source_reference: '', music_asset_id: '', chart_mode: 'regular', key_count: 4, difficulty_class: '', difficulty_value: '' as number | '', human_verified_alignment: false, group_id: '', performance_intensity: '' as number | '', performance_style: '', wildness: '' as number | '' })
const audioFacts = ref<RecordData | null>(null)
const actions = [{ value: 'local_research', label: '本地研究' }, { value: 'training', label: '模型训练' }, { value: 'distribution', label: '对外分发' }]
const ranges: Record<string, [number, number]> = { EZ: [0, 10], HD: [11, 14], IN: [14, 17], AT: [15, 18] }
const music = computed(() => state.assets.filter(a => a.name.toLowerCase().includes(query.value.toLowerCase())))
const charts = computed(() => state.charts.filter(a => a.name.toLowerCase().includes(query.value.toLowerCase())))
const knownLabelsValid = computed(() => [editor.performance_intensity, editor.wildness].every(v => v === '' || (Number.isInteger(v) && Number(v) >= 0 && Number(v) <= 100)))
const difficultyLabelsValid = computed(() => {
  if (editor.difficulty_class === '' && editor.difficulty_value === '') return true
  const bounds = ranges[editor.difficulty_class]
  return !!bounds && editor.difficulty_value !== '' && Number.isInteger(editor.difficulty_value) && Number(editor.difficulty_value) >= bounds[0] && Number(editor.difficulty_value) <= bounds[1]
})
watch(musicLicense, v => { if (v !== 'explicit_permitted') musicActions.value = musicActions.value.filter(a => a !== 'training') })
watch(() => chart.license_status, v => { if (v !== 'explicit_permitted') chart.allowed_actions = chart.allowed_actions.filter(a => a !== 'training') })
watch(() => editor.license_status, v => { if (v !== 'explicit_permitted') editor.allowed_actions = editor.allowed_actions.filter(a => a !== 'training') })
watch(() => editor.music_asset_id, v => { if (editKind.value === 'chart' && edit.value && v !== (edit.value.music_asset_id || '')) editor.human_verified_alignment = false })
watch(() => chart.difficulty_class, v => { chart.difficulty_value = Math.max(ranges[v]![0], Math.min(ranges[v]![1], chart.difficulty_value)) })
function difficultyClassChanged() {
  const bounds = ranges[editor.difficulty_class]
  if (!bounds || (editor.difficulty_value !== '' && (Number(editor.difficulty_value) < bounds[0] || Number(editor.difficulty_value) > bounds[1]))) editor.difficulty_value = ''
}
function sourceFormat(record: RecordData) { return ({ phigros_v1: 'Phigros v1', phigros_v3: 'Phigros v3', pec: 'PEC', unknown: '格式未识别' } as Record<string, string>)[record.source_format] || record.source_format || record.source_type || '格式未标注' }
function targetDifficulty(record: RecordData) { return record.difficulty_class && Number.isInteger(record.difficulty_value) ? `训练难度：${record.difficulty_class} ${record.difficulty_value}` : '目标训练难度未标注' }
function candidateFor(record: RecordData) { return record.candidate_id || state.candidates.find(c => c.manifest?.chart_asset_id === record.id)?.id || '' }
function archiveReason(record: RecordData) { const messages = (record.warnings || []).map((w: any) => typeof w === 'string' ? w : w.message || w.code || JSON.stringify(w)); return messages.slice(0, 2).join('；') || `当前 ${sourceFormat(record)} 来源未提供可预览的转换候选，仅保存原始资料。` }
async function openChart(record: RecordData) {
  const id = candidateFor(record)
  if (record.import_status === 'archived_only' || !id) return
  await perform(`open-chart-${record.id}`, async () => { const result = await api(`/candidates/${encodeURIComponent(id)}`); if (!result?.id) throw new Error('本地服务未返回有效候选，无法打开预览。'); emit('openCandidate', result.id) })
}
async function uploadMusic() {
  if (!musicFile.value) return
  await perform('upload-music', async () => { const f = new FormData(); f.set('file', musicFile.value!); f.set('license_status', musicLicense.value); f.set('allowed_actions', JSON.stringify(musicActions.value)); await api('/assets/music', 'POST', f); musicFile.value = null; if (musicInput.value) musicInput.value.value = ''; await refresh(true) }, '音乐已导入本地素材库。分析结果以本机任务实际返回为准。')
}
async function uploadChart() {
  if (!chartFile.value) return
  await perform('upload-chart', async () => { const f = new FormData(); f.set('file', chartFile.value!); for (const [key, value] of Object.entries(chart)) { if (key === 'key_count' && chart.chart_mode !== 'pure_keys') continue; if (value !== '') f.set(key, Array.isArray(value) ? JSON.stringify(value) : String(value)) } await api('/imports/chart', 'POST', f); chartFile.value = null; if (chartInput.value) chartInput.value.value = ''; await refresh(true) }, '谱面导入请求已完成，请查看解析告警与实际入库结果。')
}
function editRecord(record: RecordData, kind: string) {
  edit.value = record; editKind.value = kind
  Object.assign(editor, { license_status: record.license_status || 'unknown', allowed_actions: [...(record.allowed_actions || [])], source_reference: record.source_reference || '', music_asset_id: record.music_asset_id || '', chart_mode: record.chart_mode || 'regular', key_count: record.key_count || 4, difficulty_class: record.difficulty_class || '', difficulty_value: record.difficulty_value ?? '', human_verified_alignment: record.human_verified_alignment === true, group_id: record.group_method === 'exact_audio_bytes_only' ? '' : record.group_id || '', performance_intensity: record.chart_mode === 'pure_keys' ? 0 : record.performance_intensity ?? '', performance_style: record.chart_mode === 'pure_keys' ? 'none' : record.performance_style ?? '', wildness: record.wildness ?? '' })
}
function labelModeChanged() {
  editor.performance_intensity = editor.chart_mode === 'pure_keys' ? 0 : ''
  editor.performance_style = editor.chart_mode === 'pure_keys' ? 'none' : ''
}
async function saveRecord() {
  if (!edit.value || (editKind.value === 'chart' && (!difficultyLabelsValid.value || !knownLabelsValid.value))) return
  await perform('save-labels', async () => { const data = editKind.value === 'music' ? { license_status: editor.license_status, allowed_actions: editor.allowed_actions, source_reference: editor.source_reference } : { chart_mode: editor.chart_mode, key_count: editor.chart_mode === 'pure_keys' ? editor.key_count : null, music_asset_id: editor.music_asset_id || null, difficulty_class: editor.difficulty_class || null, difficulty_value: editor.difficulty_value === '' ? null : editor.difficulty_value, license_status: editor.license_status, allowed_actions: editor.allowed_actions, human_verified_alignment: editor.human_verified_alignment, group_id: editor.group_id.trim(), performance_intensity: editor.chart_mode === 'pure_keys' ? 0 : editor.performance_intensity === '' ? null : editor.performance_intensity, performance_style: editor.chart_mode === 'pure_keys' ? 'none' : editor.performance_style || null, wildness: editor.wildness === '' ? null : editor.wildness }; await api(editKind.value === 'music' ? `/assets/${edit.value!.id}/license` : `/charts/${edit.value!.id}/labels`, 'PATCH', data); edit.value = null; await refresh(true) }, '授权与标签已保存，原始文件保持只读。')
}
async function analyze(id: string) { await perform(`analyze-${id}`, async () => { await api(`/assets/${id}/analyze`, 'POST', {}); await refresh() }, '传统 DSP 音频分析已排队，请在任务中心查看真实进度。') }
async function readAnalysis(id: string) { await perform(`analysis-${id}`, async () => { const result = await api(`/assets/${id}/waveform`); const { peaks, ...facts } = result; audioFacts.value = { name: state.assets.find(a => a.id === id)?.name, waveform_points: peaks?.length || 0, ...facts } }) }
</script>
<template>
  <div class="page-heading"><div><p class="eyebrow">YOUR LOCAL LIBRARY</p><h1>每份素材，都有清楚的来处。</h1><p class="subtitle">导入音乐与谱面，分别记录本地研究、模型训练和分发许可。</p></div><span class="badge outline">原始文件只读</span></div>
  <div class="library-upload-grid"><section class="panel"><div class="panel-heading"><div><p class="section-kicker">音频素材</p><h2>导入一首音乐</h2></div><span class="format-chip">AUDIO</span></div><label class="upload-zone" @dragover.prevent @drop.prevent="musicFile = $event.dataTransfer?.files[0] || null"><input ref="musicInput" type="file" accept="audio/*,.wav,.flac,.mp3,.ogg,.m4a" @change="musicFile = ($event.target as HTMLInputElement).files?.[0] || null"><span class="upload-icon">♫</span><strong>{{ musicFile?.name || '点击选择或拖入音乐文件' }}</strong><small>{{ musicFile ? `${(musicFile.size / 1024 / 1024).toFixed(2)} MB · 尚未上传` : 'WAV / FLAC / MP3 / OGG 等本机可解码音频' }}</small></label><div class="field"><label>许可状态</label><select v-model="musicLicense"><option value="unknown">许可待确认</option><option value="explicit_permitted">已获得明确许可</option><option value="restricted">有限许可</option></select></div><div class="field"><label>此次素材明确允许的用途</label><div class="checkbox-row"><label v-for="a in actions" :key="a.value" class="checkbox"><input v-model="musicActions" type="checkbox" :value="a.value" :disabled="a.value === 'training' && musicLicense !== 'explicit_permitted'">{{ a.label }}</label></div><p class="field-hint">只有明确许可且勾选“模型训练”的素材才能参与训练。</p></div><button class="button primary full" :disabled="!musicFile || !state.connected || state.busy['upload-music']" @click="uploadMusic">{{ state.busy['upload-music'] ? '导入中，请等待…' : '导入音乐到本机' }}</button></section>
    <section class="panel"><div class="panel-heading"><div><p class="section-kicker">谱面素材</p><h2>导入与标注谱面</h2></div><span class="format-chip">JSON / PEZ</span></div><label class="upload-zone compact-upload" @dragover.prevent @drop.prevent="chartFile = $event.dataTransfer?.files[0] || null"><input ref="chartInput" type="file" accept=".json,.pez,.zip" @change="chartFile = ($event.target as HTMLInputElement).files?.[0] || null"><span class="upload-icon">▤</span><strong>{{ chartFile?.name || '选择 JSON / PEZ / ZIP 谱面' }}</strong><small>未知字段与已有噪域将只读保留；不兼容项明确报告。</small></label><div class="form-grid"><div class="field"><label>关联音乐</label><select v-model="chart.music_asset_id"><option value="">暂不关联（包内音频不会自动导入）</option><option v-for="a in state.assets" :key="a.id" :value="a.id">{{ a.name }}</option></select></div><div class="field"><label>谱面模式</label><select v-model="chart.chart_mode"><option value="regular">常规多线</option><option value="pure_keys">固定键位</option><option value="anomaly">特殊异像</option></select></div><div v-if="chart.chart_mode === 'pure_keys'" class="field"><label>真实键位数</label><select v-model.number="chart.key_count"><option :value="4">4K</option><option :value="5">5K</option><option :value="6">6K</option></select></div><div class="field"><label>难度类别</label><select v-model="chart.difficulty_class"><option>EZ</option><option>HD</option><option>IN</option><option>AT</option></select></div><div class="field"><label>难度数值</label><input v-model.number="chart.difficulty_value" type="number" :min="ranges[chart.difficulty_class]![0]" :max="ranges[chart.difficulty_class]![1]"></div><div class="field"><label>谱面许可</label><select v-model="chart.license_status"><option value="unknown">许可待确认</option><option value="explicit_permitted">已获得明确许可</option><option value="restricted">有限许可</option></select></div></div><div class="field"><label>谱面明确允许的用途</label><div class="checkbox-row"><label v-for="a in actions" :key="a.value" class="checkbox"><input v-model="chart.allowed_actions" type="checkbox" :value="a.value" :disabled="a.value === 'training' && chart.license_status !== 'explicit_permitted'">{{ a.label }}</label></div></div><button class="button primary full" :disabled="!chartFile || !state.connected || state.busy['upload-chart']" @click="uploadChart">{{ state.busy['upload-chart'] ? '导入中，请等待…' : '导入谱面与标签' }}</button></section></div>
  <section class="panel library-table"><div class="panel-heading"><div><p class="section-kicker">素材清单</p><h2>留在这台机器上的创作资料</h2></div><div class="search-input"><span>⌕</span><input v-model="query" placeholder="搜索素材名称" aria-label="搜索素材"></div></div><div class="tabs"><button :class="{ active: tab === 'music' }" @click="tab = 'music'">音乐 <span>{{ state.assets.length }}</span></button><button :class="{ active: tab === 'chart' }" @click="tab = 'chart'">谱面 <span>{{ state.charts.length }}</span></button></div><div class="table-scroll"><table v-if="tab === 'music'"><thead><tr><th>音乐素材</th><th>时长 / 采样</th><th>许可状态</th><th>允许用途</th><th>操作</th></tr></thead><tbody><tr v-for="a in music" :key="a.id"><td><div class="table-title"><span class="file-icon">♫</span><div><strong>{{ a.name }}</strong><small>{{ short(a.sha256) }}</small></div></div></td><td>{{ time(a.duration_s) }}<small>{{ a.sample_rate ? `${a.sample_rate} Hz · ${a.channels || '—'} 声道` : '等待音频探测' }}</small></td><td><span :class="['badge', a.license_status === 'explicit_permitted' ? 'green' : 'amber']">{{ label(a.license_status) }}</span></td><td><div class="tag-list"><span v-for="x in a.allowed_actions || []" :key="x" class="tag">{{ label(x) }}</span></div><span v-if="!a.allowed_actions?.length" class="muted">未声明</span></td><td><div class="column-actions"><button class="text-button" :disabled="state.busy[`analyze-${a.id}`]" @click="analyze(a.id)">分析 / 重算音频</button><button class="text-button" :disabled="state.busy[`analysis-${a.id}`]" @click="readAnalysis(a.id)">查看分析摘要</button><button class="text-button" @click="editRecord(a, 'music')">查看 / 更新许可</button></div></td></tr><tr v-if="!music.length"><td colspan="5"><div class="empty"><span class="empty-icon">♫</span><strong>{{ query ? '没有匹配的音乐' : '素材库还没有音乐' }}</strong><p>使用上方入口导入本地音频。</p></div></td></tr></tbody></table><table v-else><thead><tr><th>谱面素材</th><th>原始级别 / 训练标签</th><th>授权 / 对齐</th><th>解析告警</th><th>操作</th></tr></thead><tbody><tr v-for="a in charts" :key="a.id"><td><div class="table-title"><span class="file-icon">▤</span><div><strong>{{ a.name }}</strong><small>{{ short(a.sha256) }}</small><small v-if="a.source_type === 'official'">官谱来源（用户声明，未验证）</small></div></div></td><td><strong>{{ a.source_level || '原始级别未提供' }}</strong><small>{{ targetDifficulty(a) }}</small><small>{{ label(a.chart_mode) }} {{ a.key_count ? `${a.key_count}K` : '' }} · {{ sourceFormat(a) }}</small></td><td><span :class="['badge', a.license_status === 'explicit_permitted' ? 'green' : 'amber']">{{ label(a.license_status) }}</span><small>{{ a.allowed_actions?.map(label).join(' / ') || '未声明用途' }} · {{ a.human_verified_alignment ? '人工确认已对齐' : '对齐待人工确认' }}</small></td><td><details v-if="a.warnings?.length"><summary class="warning-text">{{ a.warnings.length }} 项告警</summary><pre>{{ JSON.stringify(a.warnings, null, 2) }}</pre></details><span v-else class="muted">未列出告警</span></td><td><div class="column-actions"><span v-if="a.import_status" :class="['badge', a.import_status === 'archived_only' ? 'amber' : 'blue']">{{ a.import_status === 'archived_only' ? '仅存档 · 尚无转换候选' : '已转换 · 待审核' }}</span><button class="text-button" :disabled="a.import_status === 'archived_only' || !candidateFor(a) || state.busy[`open-chart-${a.id}`]" @click="openChart(a)">查看候选 / 参考预览</button><p v-if="a.import_status === 'archived_only'" class="field-hint">{{ archiveReason(a) }}</p><small v-else-if="!candidateFor(a)" class="muted">尚无可预览候选</small><button class="text-button" @click="editRecord(a, 'chart')">核对 / 更新标签</button></div></td></tr><tr v-if="!charts.length"><td colspan="5"><div class="empty"><span class="empty-icon">▤</span><strong>{{ query ? '没有匹配的谱面' : '素材库还没有谱面' }}</strong><p>导入 JSON 或 PEZ，并明确标注使用许可。</p></div></td></tr></tbody></table></div></section>
  <div v-if="audioFacts" class="modal-backdrop" @click.self="audioFacts = null"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="analysis-heading"><div class="panel-heading"><div><p class="section-kicker">传统 DSP 分析结果</p><h2 id="analysis-heading">{{ audioFacts.name }}</h2></div><button class="icon-button" aria-label="关闭音频分析" @click="audioFacts = null">×</button></div><p v-if="audioFacts.status === 'NOT_ANALYZED'" class="soft-callout">尚未执行音频分析，请先点击“分析 / 重算音频”。</p><p v-else class="small-text muted">以下为本地服务实际返回的节拍与起音证据。BPM 是启发式估计，需人工听音核对。</p><pre>{{ JSON.stringify(audioFacts, null, 2) }}</pre></section></div><div v-if="edit" class="modal-backdrop" @click.self="edit = null"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="license-heading"><div class="panel-heading"><div><p class="section-kicker">人工确认</p><h2 id="license-heading">{{ edit.name }}</h2></div><button class="icon-button" aria-label="关闭" @click="edit = null">×</button></div><p class="small-text muted">许可和标签独立记录，原始音乐或谱面不改写。请按你实际获得的授权保存。</p><div class="field"><label>许可状态</label><select v-model="editor.license_status"><option value="unknown">许可待确认</option><option value="explicit_permitted">已获得明确许可</option><option value="restricted">有限许可</option></select></div><div class="field"><label>明确允许的用途</label><div class="checkbox-row"><label v-for="a in actions" :key="a.value" class="checkbox"><input v-model="editor.allowed_actions" :value="a.value" type="checkbox" :disabled="a.value === 'training' && editor.license_status !== 'explicit_permitted'">{{ a.label }}</label></div></div><div v-if="editKind === 'music'" class="field"><label>授权来源说明</label><textarea v-model="editor.source_reference" rows="3" placeholder="例如：自制音乐 / 作者授权及其范围"></textarea></div><template v-else><div v-if="edit.source_level || edit.source_format || edit.import_status" class="soft-callout"><strong>原始级别：{{ edit.source_level || '未提供' }}</strong><p>{{ sourceFormat(edit) }} · {{ targetDifficulty(edit) }}</p><p v-if="edit.source_type === 'official'">官谱来源由用户声明，来源与使用权尚未验证；不会自动获得训练许可。</p><p v-if="edit.import_status === 'archived_only'">仅存档：{{ archiveReason(edit) }} 修改标签不会自动完成转换或建立预览候选。</p><p v-if="edit.source_difficulty_value != null">原始难度数值 {{ edit.source_difficulty_value }} 只供查阅，不自动舍入为训练标签。</p></div><div class="field"><label>关联音乐（从本机素材选择）</label><select v-model="editor.music_asset_id"><option value="">暂不关联</option><option v-for="a in state.assets" :key="a.id" :value="a.id">{{ a.name }}</option></select><p class="field-hint">重新关联后请重新实际听音确认时间对齐。</p></div><div class="form-grid"><div class="field"><label>真实谱面模式</label><select v-model="editor.chart_mode" @change="labelModeChanged"><option value="regular">常规多线</option><option value="pure_keys">固定键位</option><option value="anomaly">特殊异像</option></select></div><div v-if="editor.chart_mode === 'pure_keys'" class="field"><label>键位数</label><select v-model.number="editor.key_count"><option :value="4">4K</option><option :value="5">5K</option><option :value="6">6K</option></select></div><div class="field"><label>目标训练难度类别（可选）</label><select v-model="editor.difficulty_class" @change="difficultyClassChanged"><option value="">未标注 · 由你明确选择</option><option>EZ</option><option>HD</option><option>IN</option><option>AT</option></select></div><div class="field"><label>目标训练难度整数（可选）</label><input v-model.number="editor.difficulty_value" type="number" step="1" :min="ranges[editor.difficulty_class]?.[0] ?? 0" :max="ranges[editor.difficulty_class]?.[1] ?? 18" :disabled="!editor.difficulty_class" placeholder="未标注 · 不自动舍入"><p class="field-hint">类别与整数需同时填写，或同时留空。原始级别保持只读。</p></div></div><div class="soft-callout"><strong>可选的已知条件标签</strong><p>仅填写你实际确认的演出与配置标签；留空表示未标注，不按 0 或标准风格猜测。固定键位的演出强度与风格由模式约束锁定。</p></div><div class="form-grid"><div class="field"><label>演出强度（可选）</label><input v-model.number="editor.performance_intensity" type="number" min="0" max="100" step="1" placeholder="未标注 · 0–100" :disabled="editor.chart_mode === 'pure_keys'"></div><div class="field"><label>演出风格（可选）</label><select v-model="editor.performance_style" :disabled="editor.chart_mode === 'pure_keys'"><option value="">未标注</option><option value="none">无演出</option><option value="calm">克制</option><option value="standard">标准</option><option value="rhythm_linked">跟随节奏</option><option value="ornate">丰富</option><option value="experimental">实验</option></select></div><div class="field"><label>狂野度（可选）</label><input v-model.number="editor.wildness" type="number" min="0" max="100" step="1" placeholder="未标注 · 0–100"><p class="field-hint">固定键位中仅描述键位组合，不表示判定线运动。</p></div></div><div class="field"><label>同源歌曲分组 ID（训练必填）</label><input v-model="editor.group_id" placeholder="同歌的不同难度与剪辑使用同一个分组 ID"><p class="field-hint">请手填歌曲簇 ID。同歌的转码、剪辑与不同难度必须同组；空缺时不能加入训练。</p></div><label class="checkbox"><input v-model="editor.human_verified_alignment" type="checkbox"><span>我已实际听音并核对该谱面与所关联音乐的时间对齐。</span></label></template><div class="form-footer"><button class="button secondary" @click="edit = null">取消</button><button class="button primary" :disabled="state.busy['save-labels'] || (editKind === 'chart' && (!knownLabelsValid || !difficultyLabelsValid))" @click="saveRecord">确认并保存</button></div></section></div>
</template>
